export default {"id":"lore-compose","title":"New Lore · Comos","bodyClass":"app","layout":"app","header":"<header><a class=\"brand\" href=\"index.html\"><span class=\"mark\" aria-hidden=\"true\">✦</span><span>Comos</span></a><nav class=\"main-nav\" aria-label=\"Main\"><a href=\"home.html\">Home</a><a href=\"lore.html\" aria-current=\"page\">Lore</a><a href=\"characters.html\">Characters</a></nav><a class=\"account\" href=\"account.html\"><svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"8\" r=\"3.5\"/><path d=\"M4 21v-3a8 8 0 0 1 16 0v3\"/></svg><span class=\"sr-only\">Account</span></a></header>","main":"<section class=\"comos-composer comos-lore-composer\" data-lore-compose>\n  <a class=\"back\" href=\"lore.html\">← Lore</a>\n  <h1>New Lore</h1>\n  <form data-lore-compose-form>\n    <label for=\"lore-title\">Title</label>\n    <input id=\"lore-title\" name=\"title\" required maxlength=\"140\" placeholder=\"Give your Lore a title\" autocomplete=\"off\">\n    <label>Content</label>\n    <div class=\"comos-lore-edit-blocks\" data-lore-blocks aria-label=\"Lore paragraphs and images\"></div>\n    <div class=\"comos-lore-add-tools\">\n      <button class=\"button\" type=\"button\" data-add-lore-paragraph>+ Paragraph</button>\n      <label class=\"button\" for=\"lore-image-files\">+ Image</label>\n      <input type=\"file\" id=\"lore-image-files\" data-lore-image-files accept=\"image/jpeg,image/png,image/webp\" multiple hidden>\n      <button class=\"comos-lore-compose-tag-button\" type=\"button\" data-lore-open-tags aria-label=\"Choose character tags\" title=\"Character tags\">\n        <svg viewBox=\"0 0 24 24\" width=\"21\" height=\"21\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 4h9l9 9-8 8-10-10V4Z\"/><circle cx=\"8\" cy=\"9\" r=\"1.5\"/></svg>\n        <span data-lore-tag-count hidden></span>\n      </button>\n    </div>\n    <div class=\"comos-lore-selected-tags\" data-lore-selected-tags></div>\n    <p class=\"comos-count\" data-lore-count>0 / 10000</p>\n    <p role=\"status\" aria-live=\"polite\" data-lore-compose-status>Checking account…</p>\n    <div class=\"comos-lore-draft-tools\"><p role=\"status\" aria-live=\"polite\" data-lore-draft-status>Preparing autosave…</p><button type=\"button\" data-lore-discard-draft hidden>Clear draft</button></div>\n    <button class=\"button primary\" type=\"submit\" data-lore-publish disabled>Publish Lore</button>\n  </form>\n  <dialog class=\"comos-lore-popup\" data-lore-compose-tag-dialog aria-label=\"Choose character tags\">\n    <div class=\"comos-lore-popup-heading\"><h2>Character tags</h2><button type=\"button\" class=\"comos-lore-popup-close\" data-lore-tags-close aria-label=\"Close tags\">×</button></div>\n    <div data-lore-tag-options></div>\n    <small>Only tags attached to your characters are available.</small>\n  </dialog>\n</section>"};
